/// Error enum for MPA
public struct MPAErrorType: AWSErrorType, Decodable {
    @nonexhaustive
    public enum Code: Sendable {
        /// You do not have sufficient access to perform this action. Check your permissions, and try again.
        case accessDeniedException
        /// The request cannot be completed because it conflicts with the current state of a resource.
        case conflictException
        /// The service encountered an internal error. Try your request again. If the problem persists, contact Amazon Web Services Support.
        case internalServerException
        /// The request contains an invalid parameter value.
        case invalidParameterException
        /// The specified resource doesn't exist. Check the resource ID, and try again.
        case resourceNotFoundException
        /// The request exceeds the service quota for your account. Request a quota increase or reduce your request size.
        case serviceQuotaExceededException
        /// The request was denied due to request throttling.
        case throttlingException
        /// The request exceeds the maximum number of tags allowed for this resource. Remove some tags, and try again.
        case tooManyTagsException(MPA.TooManyTagsException)
        /// The input fails to satisfy the constraints specified by an Amazon Web Services service.
        case validationException
    }

    public let error: Code
    public let message: String?
    public let response: HTTPResponse?

    public init(from decoder: any Decoder) throws {
        let singleValueContainer = try decoder.singleValueContainer()
        let errorCode = try singleValueContainer.decode(AWSErrorCode.self)
        switch errorCode.code {
        case "AccessDeniedException": self.error = .accessDeniedException
        case "ConflictException": self.error = .conflictException
        case "InternalServerException": self.error = .internalServerException
        case "InvalidParameterException": self.error = .invalidParameterException
        case "ResourceNotFoundException": self.error = .resourceNotFoundException
        case "ServiceQuotaExceededException": self.error = .serviceQuotaExceededException
        case "ThrottlingException": self.error = .throttlingException
        case "TooManyTagsException":
            let context = try singleValueContainer.decode(MPA.TooManyTagsException.self)
            self.error = .tooManyTagsException(context)
        case "ValidationException": self.error = .validationException
        default:
            throw DecodingError.dataCorrupted(.init(codingPath: decoder.codingPath, debugDescription: "Unrecognised error code"))
        }
        self.message = try singleValueContainer.decode(AWSErrorMessage.self).message
        self.response = (decoder.userInfo[.awsResponse]! as! ResponseDecodingContainer).response.response
    }

    /// return error code string
    public var errorCode: String {
        switch error {
        case .accessDeniedException: "AccessDeniedException"
        case .conflictException: "ConflictException"
        case .internalServerException: "InternalServerException"
        case .invalidParameterException: "InvalidParameterException"
        case .resourceNotFoundException: "ResourceNotFoundException"
        case .serviceQuotaExceededException: "ServiceQuotaExceededException"
        case .throttlingException: "ThrottlingException"
        case .tooManyTagsException: "TooManyTagsException"
        case .validationException: "ValidationException"
        }
    }
